Q: CRUD with MVC in win application c# A: <p>Data</p>
<pre><code>using EntityFrameworkProject.Models;
using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;

namespace EntityFrameworkProject.Data
{
    public class AppDbContext : IdentityDbContext&lt;AppUser&gt;
    {
        public AppDbContext(DbContextOptions&lt;AppDbContext&gt; options) : base(options) { }

        public DbSet&lt;Slider&gt; Sliders { get; set; }
        public DbSet&lt;SliderDetail&gt; SliderDetails { get; set; }
        public DbSet&lt;Product&gt; Products { get; set; }
        public DbSet&lt;ProductImage&gt; ProductImages { get; set; }
        public DbSet&lt;Category&gt; Categories { get; set; }
        public DbSet&lt;Setting&gt; Settings { get; set; }
        public DbSet&lt;ProductTag&gt; ProductTags { get; set; }

        protected override void OnModelCreating(ModelBuilder modelBuilder)
        {
            base.OnModelCreating(modelBuilder);
            modelBuilder.Entity&lt;Blog&gt;().HasQueryFilter(m =&gt; !m.IsDeleted);
            modelBuilder.Entity&lt;Blog&gt;().HasData(
            new Blog
            {
                Id = 1,
                Image = &quot;blog-feature-img-1.jpg&quot;,
                Title = &quot;Flower Power&quot;,
                Description = &quot;Class aptent taciti sociosqu ad litora torquent per conubia nostra, per&quot;,
                CreatedDate = new DateTime(2025, 12, 22),
                IsDeleted = false
            },

            new Blog
            {
                Id = 2,
                Image = &quot;blog-feature-img-3.jpg&quot;,
                Title = &quot;Local Florists&quot;,
                Description = &quot;This is the first post in our blog. Stay tuned for more updates!&quot;,
                CreatedDate = new DateTime(2025, 12, 22),
                IsDeleted = false
            },

            new Blog
            {
                Id = 3,
                Image = &quot;blog-feature-img-4.jpg&quot;,
                Title = &quot;Flower Beauty&quot;,
                Description = &quot;This is the first post in our blog. Stay tuned for more updates!&quot;,
                CreatedDate = new DateTime(2025, 12, 22),
                IsDeleted = false
            }
                );
        }
    }
}
</code></pre>

Q: How to create a custom ListBox in C# WinForms (Visual Studio 2022) A: <p>Set the <code>DrawMode</code> to <code>OwnerDrawFixed</code> and override <code>OnDrawItem</code> where you put your drawing logic.</p>
<p>Here is an example of a <code>ListBox</code> displaying font names along with a font example:</p>
<pre class="lang-cs prettyprint-override"><code>public class FontFamilyListBox : ListBox
{
    public FontFamilyListBox()
    {
        IntegralHeight = false;
        SelectionMode = SelectionMode.One;
        ItemHeight = Math.Max(ItemHeight, 18);
        Height = 16 * ItemHeight + 3;
        DrawMode = DrawMode.OwnerDrawFixed;

        foreach (var family in FontFamily.Families) {
            Items.Add(family.Name);
        }
    }

    protected override void OnDrawItem(DrawItemEventArgs e)
    {
        const string ExampleText = &quot;Abc 123&quot;;

        string fontFamilyName = (string)Items[e.Index];
        using var itemFont = new Font(fontFamilyName, 12);
        using var brush = new SolidBrush(e.ForeColor);
        e.DrawBackground();
        e.Graphics.DrawString(itemFont.Name, Font, brush, e.Bounds.X, e.Bounds.Y);

        float textWidth = e.Graphics.MeasureString(itemFont.Name, Font).Width;
        float exampleWidth = e.Graphics.MeasureString(ExampleText, itemFont).Width;
        if (textWidth + exampleWidth + 3 &lt; e.Bounds.Width) {
            e.Graphics.DrawString(ExampleText, itemFont, brush, e.Bounds.Right - exampleWidth - 1, e.Bounds.Y);
        }
        e.DrawFocusRectangle();
    }
}
</code></pre>
